(function(){'use strict';
/* Engines Database generator — jahdb-engines-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = Fact-checked public information */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-ENGINES-';
var SRC='public';
var RECORD_KIND='engine record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"title":"Internal Combustion Engines","brief":"A piston engine that burns fuel inside its cylinders, turning expanding gases into rotating shaft power through the intake, compression, power, and exhaust strokes.","points":["Fuel and air mix inside the cylinder, and a spark or compression ignites it to drive the piston down.","The crankshaft converts the pistons' reciprocating motion into rotary motion that drives wheels or propellers.","Thermal efficiency of a typical gasoline engine is 20-30 percent; the rest leaves as heat and exhaust.","Engines are classed by cylinder count, arrangement (inline, V, flat, radial), displacement, and fuel type."],"examples":["A family sedan's 2.0-liter four-cylinder cruising at highway speed.","A V8 pickup towing a trailer, using torque from large displacement at low rpm."],"history":["Nicolaus Otto built the first practical four-stroke engine in 1876, the template for nearly all gasoline engines.","Rudolf Diesel patented the compression-ignition engine in 1892, aiming for higher efficiency than steam."],"uses":["Passenger cars, trucks, motorcycles, and boats all run on internal combustion variants.","Portable generators and construction equipment rely on small gasoline and diesel engines.","Aviation's general-aviation fleet still flies behind piston engines derived from 1930s designs."],"qa":[["Why do engines get hot?","Only a fraction of fuel energy becomes motion; most becomes heat that the cooling system must remove."],["What does displacement mean?","The total volume swept by all pistons — bigger displacement generally means more power potential."],["Do all engines use spark plugs?","No — gasoline engines do, but diesels ignite fuel purely through compression heat."]]},{"title":"Diesel Engines","brief":"Compression-ignition engines that squeeze air until it is hot enough to ignite injected fuel, delivering high torque and fuel efficiency.","points":["Compression ratios of 14:1 to 22:1 heat intake air above 500 C, so injected diesel self-ignites.","Diesels run lean — no throttle plate — which keeps part-load efficiency far above gasoline engines.","High torque at low rpm makes diesels the choice for trucks, ships, trains, and heavy equipment.","Modern common-rail injection fires multiple precisely timed pulses per stroke to cut noise and emissions."],"examples":["A semi truck climbing a grade at 1,200 rpm in top gear.","A backup generator at a hospital starting automatically during a power outage."],"history":["Rudolf Diesel demonstrated his engine at the 1900 Paris Exposition running on peanut oil.","Robert Bosch's 1927 fuel-injection pump made compact high-speed diesels practical for trucks."],"uses":["Nearly all long-haul freight, rail locomotives, and ocean shipping run on diesel power.","Diesels drive farm tractors, mining trucks, and construction machinery worldwide.","Diesel generators provide prime and emergency power in remote and critical facilities."],"qa":[["Why are diesels louder?","The violent compression-ignition event and high cylinder pressures create the characteristic knock."],["Can diesels run on vegetable oil?","With conversion kits and heated fuel systems, yes — Diesel's first engines ran on plant oils."],["Why do diesels last longer?","Heavier construction for high pressures plus low-rpm operation means less wear per mile."]]},{"title":"Gasoline Direct Injection","brief":"Fuel systems that spray gasoline directly into the combustion chamber at high pressure for finer control, better efficiency, and more power.","points":["Injectors fire fuel at 2,000-3,500 psi straight into the cylinder during the intake or compression stroke.","Stratified charge modes run very lean at light load, cutting fuel use by 10-20 percent over port injection.","Precise injection timing cools the charge, allowing higher compression ratios without knock.","Direct injection can raise particulate emissions, so many engines pair it with a particulate filter."],"examples":["A turbocharged sport sedan making 300 hp from a 2.0-liter direct-injected four.","An economy car hitting 40 mpg highway partly thanks to direct injection."],"history":["Mitsubishi launched the first modern GDI car engine, the 4G93, in Japan in 1996.","By the 2010s direct injection had become standard on most new gasoline engines worldwide."],"uses":["Most new gasoline cars and light trucks use direct injection as standard equipment.","Performance engines pair GDI with turbocharging for high specific output.","Motorcycle and marine engines are adopting GDI for efficiency and emissions."],"qa":[["Is direct injection reliable?","Yes, but intake valves can accumulate carbon since fuel no longer washes them — periodic cleaning helps."],["Does it need premium fuel?","Not always, but high-compression GDI engines often recommend it to prevent knock."],["Can you convert an old engine to GDI?","No — it requires a redesigned cylinder head, high-pressure pump, and engine computer."]]},{"title":"Turbocharging","brief":"Using exhaust gas to spin a turbine that forces extra air into the engine, boosting power far beyond what displacement alone allows.","points":["A turbine in the exhaust stream drives a compressor that packs denser air into the cylinders.","More air means more fuel can burn, raising power 30-50 percent or more from the same displacement.","Turbo lag — the delay while the turbo spools — is reduced with twin-scroll, variable-geometry, and electric-assist turbos.","Intercoolers chill the compressed air, making it denser and preventing detonation."],"examples":["A 1.5-liter turbo four matching the power of an older 2.5-liter naturally aspirated engine.","A diesel pickup towing heavy loads with turbo boost filling in low-end torque."],"history":["Swiss engineer Alfred Buchi patented the turbocharger in 1905; aircraft used them in the 1920s-30s.","The 1962 Oldsmobile Jetfire was the first production car with a turbocharger."],"uses":["Nearly all modern diesels and a growing majority of gasoline cars are turbocharged.","Turbochargers are mandatory equipment on heavy trucks and industrial diesels.","Aircraft piston engines use turbos to hold power at altitude where air is thin."],"qa":[["Does a turbo hurt reliability?","Modern turbos last the engine's life if oil changes are done — heat is their main enemy."],["Should I idle before shutting down?","After hard driving, a short cool-down protects the turbo's oil-fed bearings."],["Turbo vs supercharger?","Turbos use free exhaust energy and are more efficient; superchargers respond instantly but consume crank power."]]},{"title":"Supercharging","brief":"Belt-, gear-, or electrically driven compressors that force extra air into the engine for instant, lag-free boost.","points":["A supercharger is mechanically driven off the crankshaft, so boost is available immediately at any rpm.","Roots, twin-screw, and centrifugal designs each trade efficiency, packaging, and boost character differently.","Superchargers consume engine power to make power — typically 10-20 percent of output at full boost.","Electric superchargers use a motor to spool instantly, filling the gap before an exhaust turbo wakes up."],"examples":["A muscle car with a Roots blower whining under the hood at full throttle.","A mild-hybrid SUV using a 48-volt electric supercharger to erase turbo lag."],"history":["Gottlieb Daimler patented a supercharger design in 1885; Mercedes raced supercharged cars in the 1920s.","Top-fuel dragsters still use giant Roots superchargers to make over 11,000 horsepower."],"uses":["High-performance street cars use superchargers for predictable, linear power delivery.","Drag racing's top classes are defined by supercharged V8 engines.","Marine and industrial engines use supercharging where instant response matters."],"qa":[["Why choose a supercharger over a turbo?","Instant throttle response and simpler packaging, at the cost of some efficiency."],["Do superchargers need intercoolers?","At higher boost levels, yes — compressed air gets hot and needs cooling."],["Can you add one to any engine?","Kits exist for many engines, but fueling, tuning, and internals must handle the extra pressure."]]},{"title":"Rotary (Wankel) Engines","brief":"Pistonless engines where a triangular rotor spins inside an epitrochoid housing, completing intake, compression, power, and exhaust with smooth rotation.","points":["A triangular rotor orbits an eccentric shaft, creating three moving combustion chambers.","Each rotor face fires once per revolution, giving high power from tiny displacement — 1.3 liters making 230+ hp.","Rotaries rev smoothly to 9,000+ rpm with almost no vibration, since nothing reciprocates.","Apex seals at the rotor tips wear faster than piston rings, historically limiting longevity and raising oil use."],"examples":["A Mazda RX-7's 13B rotary screaming to redline with its signature exhaust note.","A compact aircraft auxiliary power unit chosen for its light weight and smoothness."],"history":["Felix Wankel conceived the rotary in the 1920s; NSU built the first running prototype in 1957.","Mazda commercialized it with the 1967 Cosmo Sport and refined it for five decades through the RX-8."],"uses":["Sports cars like the RX-7 and RX-8 made the rotary famous for light, high-revving performance.","Rotaries power drones, karts, and experimental aircraft where weight matters most.","Mazda now uses a rotary as a compact range extender in electric vehicles."],"qa":[["Why did rotaries fade?","Fuel consumption and emissions rules penalized their thirsty, oil-burning design."],["Are they reliable?","Well-maintained ones run long; neglect of cooling and oil kills apex seals quickly."],["Will the rotary return?","As a small range-extender generator running at constant rpm, its compactness shines again."]]},{"title":"Two-Stroke Engines","brief":"Engines that complete the power cycle in one crankshaft revolution, firing every stroke for high power-to-weight in a simple package.","points":["Intake, compression, power, and exhaust happen in just two piston strokes using ports instead of valves.","Firing every revolution doubles the power pulses of a four-stroke of the same size.","Oil mixes with the fuel for lubrication, which is why two-strokes smoke and pollute more.","Expansion-chamber exhausts use pressure waves to supercharge the cylinder, a black art of two-stroke tuning."],"examples":["A chainsaw screaming at 13,000 rpm in a logger's hands.","A classic 1970s dirt bike with the smell and ring-ding of premix exhaust."],"history":["Dugald Clerk patented the two-stroke in 1881; Joseph Day simplified it with crankcase scavenging in 1889.","Two-strokes dominated motorcycles and outboards until emissions rules pushed four-strokes in the 2000s."],"uses":["Chainsaws, trimmers, blowers, and small outboards still favor two-stroke simplicity and light weight.","Large marine diesels are two-strokes — the biggest engines on Earth, up to 100,000+ hp.","Model aircraft and RC engines use tiny two-strokes for power density."],"qa":[["Why are they being phased out?","Burning lubricating oil with the fuel makes their exhaust dirty by modern standards."],["Are they more powerful?","Per displacement, yes — but per fuel burned and per emissions, four-strokes win."],["Do any cars still use them?","Essentially none new; direct-injection two-stroke research continues for niche uses."]]},{"title":"Four-Stroke Cycle","brief":"The intake-compression-power-exhaust sequence behind nearly every car engine, described by the Otto cycle.","points":["Intake: the piston descends, drawing in the air-fuel mixture through open intake valves.","Compression: both valves close and the piston rises, squeezing the mixture to a fraction of its volume.","Power: the spark fires, expanding gases drive the piston down — the only stroke that makes power.","Exhaust: the exhaust valve opens and the rising piston pushes spent gases out."],"examples":["Watching a cutaway engine model cycle through all four strokes by hand.","A cylinder misfire felt as a stumble — one power stroke in the sequence went missing."],"history":["Nicolaus Otto's 1876 engine ran the first practical four-stroke cycle.","Alphonse Beau de Rochas had described the four-stroke principle in an 1862 patent."],"uses":["Every gasoline car, most motorcycles, and light aircraft engines run four-stroke cycles.","Lawn mowers, generators, and pressure washers use small four-strokes.","Large diesels in ships and power plants scale the same cycle to enormous size."],"qa":[["Why four strokes instead of two?","Separate intake and exhaust strokes allow cleaner breathing and far lower emissions."],["What is valve overlap?","A brief moment when both valves are open, helping scavenge exhaust at high rpm."],["Does the cycle differ for diesels?","The strokes are identical; only ignition — compression heat instead of a spark — differs."]]},{"title":"Engine Cooling Systems","brief":"Systems that reject waste heat from the engine, holding metal temperatures in the narrow band where oil works and parts survive.","points":["Liquid cooling pumps coolant through jackets around cylinders and heads, then through a radiator.","The thermostat stays shut until operating temperature, then meters flow to hold ~195-220 F.","Air-cooled engines use finned cylinders and fan-driven airflow — simpler, noisier, less precise.","Overheating warps heads and blows gaskets; undercooling raises wear and emissions."],"examples":["A radiator fan roaring on a hot day in stop-and-go traffic.","A vintage VW Beetle or Porsche 911 with fan-cooled finned cylinders."],"history":["Early cars used thermosiphon cooling with no pump; water pumps became standard by the 1920s.","Pressurized cooling systems in the 1930s raised boiling points and allowed hotter, more efficient engines."],"uses":["Every liquid-cooled car, truck, and motorcycle depends on its cooling system daily.","Race engines use enlarged radiators, oil coolers, and ducted airflow to survive full power.","Stationary generators and industrial engines use remote radiators or cooling towers."],"qa":[["Can I drive with the temperature gauge high?","Not far — pull over; minutes of overheating can warp the head."],["Why does coolant need changing?","Its anti-corrosion additives deplete, and old coolant can eat water pumps and gaskets."],["Air vs liquid cooling?","Liquid holds tighter temperature control for emissions and efficiency; air is simpler and lighter."]]},{"title":"Engine Lubrication Systems","brief":"Pressurized oil circuits that separate moving metal surfaces, cool pistons, clean contaminants, and seal rings.","points":["The oil pump draws from the sump and pushes oil through the filter to bearings, cam, and valve gear.","Hydrodynamic bearings ride on a thin oil film — metal never touches metal at speed.","Oil also cools piston undersides via squirters and carries wear particles to the filter.","Viscosity grades like 5W-30 describe flow when cold (5W) and hot (30); synthetics resist breakdown far longer."],"examples":["The oil-pressure light flickering at idle — a warning never to ignore.","A high-mileage engine kept alive by strict 5,000-mile synthetic oil changes."],"history":["Pressure-fed lubrication replaced splash systems in the 1910s-20s as engines revved higher.","Full-flow oil filters became standard in the 1940s-50s, doubling practical engine life."],"uses":["Every internal combustion engine depends on its oil system for survival.","Turbos, with red-hot shafts spinning at 200,000 rpm, live or die on clean oil supply.","Industrial diesels run oil analysis programs, changing oil by lab results rather than miles."],"qa":[["How often should I change oil?","Follow the manual — typically 5,000-10,000 miles with modern synthetics."],["Is synthetic worth it?","Yes for turbos, extreme temperatures, and extended intervals; it resists sludge far better."],["What does dark oil mean?","Normal — oil darkens as it suspends soot and contaminants; that's its job."]]},{"title":"Fuel Injection Systems","brief":"Precise metering of fuel into the engine, replacing carburetors with electronic control of every pulse.","points":["Injectors are solenoid valves that spray atomized fuel in millisecond pulses.","The ECU calculates pulse width from airflow, rpm, temperature, and oxygen-sensor feedback.","Multi-port injection sprays at each intake valve; direct injection fires inside the cylinder.","Fuel pressure regulators and pumps maintain exact rail pressure for consistent spray."],"examples":["A cold engine starting instantly with no choke — the ECU enriches the mixture automatically.","A flex-fuel vehicle switching between gasoline and E85 with the computer adjusting timing."],"history":["Bosch's mechanical injection appeared on the 1954 Mercedes 300SL; electronic systems followed in the 1960s-70s.","By the 1990s fuel injection had fully replaced carburetors on new cars."],"uses":["Every modern car, truck, motorcycle, and outboard uses electronic fuel injection.","Diesels use ultra-high-pressure common-rail injection for clean, quiet combustion.","Racing engines use staged injectors for precise fueling across huge rpm ranges."],"qa":[["Why did carburetors disappear?","Injection meters fuel far more precisely, cutting emissions and improving economy and starting."],["What is a clogged injector symptom?","Misfires, rough idle, and poor economy — cleaning or replacement restores spray pattern."],["Do injectors wear out?","They can after 100k+ miles; deposits and electrical fatigue are the usual culprits."]]},{"title":"Carburetors","brief":"Mechanical fuel mixers that used venturi vacuum to draw fuel into the airstream — the standard for most of automotive history.","points":["Air rushing through a venturi creates low pressure that pulls fuel from the float bowl through jets.","The choke richens the mixture for cold starts; the accelerator pump adds a squirt when the throttle snaps open.","Jets, needles, and floats meter fuel with no electronics — tuneable with hand tools and patience.","Carburetors can't adapt to altitude, temperature, or emissions demands the way injection can."],"examples":["A classic Mustang's four-barrel opening its secondaries with a roar.","A small-block Chevy idling rough until its choke warms up on a winter morning."],"history":["Karl Benz patented a carburetor-like device in 1888; the float-feed design matured by 1900.","Carburetors ruled for 90 years until fuel injection took over in the 1980s-90s."],"uses":["Vintage cars, classic motorcycles, and aircraft still run carburetors.","Small engines — mowers, tillers, older outboards — use simple carburetors.","Racing classes like NASCAR used carburetors into the 2010s by rule."],"qa":[["Should I convert my classic to fuel injection?","For drivability and reliability, yes — but purists keep carburetors for originality."],["Why does my carbureted bike need the choke?","Cold fuel doesn't vaporize well, so extra fuel is needed to get a combustible mix."],["Are carburetors hard to tune?","They reward patience: jets, needles, floats, and synchronization all interact."]]},{"title":"Ignition Systems","brief":"The high-voltage systems that fire spark plugs at exactly the right instant, thousands of times per minute.","points":["Coils step 12 volts up to 20,000-50,000 volts to jump the plug gap.","Distributors once routed spark to each cylinder; modern coil-on-plug gives every plug its own coil.","Timing advances with rpm and load — firing earlier at speed so peak pressure lands just after top dead center.","Knock sensors let the ECU run timing at the edge of detonation for maximum efficiency."],"examples":["A tune-up replacing worn plugs and coils curing a highway-speed misfire.","A magneto on a small engine or aircraft firing sparks with no battery at all."],"history":["Charles Kettering's 1910 Delco electric ignition replaced hand cranks and magnetos on cars.","Electronic ignition in the 1970s and coil-on-plug in the 1990s ended points and distributors."],"uses":["Every gasoline engine needs an ignition system matched to its speed and compression.","Aircraft use dual magnetos for redundancy — each plug fired by two independent systems.","Lawn equipment and chainsaws use simple magneto ignition for reliability."],"qa":[["How long do spark plugs last?","Copper ~30k miles; platinum/iridium 60k-100k+ miles."],["What causes a misfire code?","Usually a worn plug, failed coil, or injector issue on that cylinder."],["Do diesels have ignition systems?","No spark system — but they have glow plugs to aid cold starts."]]},{"title":"Spark Plugs","brief":"Small ceramic-and-metal devices that ignite the mixture millions of times, reading engine health in their deposits.","points":["A precisely gapped electrode pair sparks 15-50 times per second at highway cruise.","Heat range describes how fast the plug sheds heat — too hot causes pre-ignition, too cold fouls.","Iridium and platinum tips resist erosion, stretching service to 100,000 miles.","Plug color tells stories: tan is healthy, black is rich, white is lean, oily is worn rings."],"examples":["Reading plugs after a track day to check whether the tune runs rich or lean.","A boat engine fouling plugs from too much idling — solved with hotter plugs or less idle."],"history":["Edmond Berger is credited with an early spark plug patent in 1839; Bosch commercialized them by 1902.","Long-life precious-metal plugs in the 1980s-90s ended the era of yearly plug changes."],"uses":["Every gasoline engine from chainsaws to supercars fires on spark plugs.","Mechanics read plugs as a diagnostic window into combustion health.","Racing teams index plugs (aligning the ground strap) to squeeze the last horsepower."],"qa":[["Can I gap iridium plugs?","Carefully — never pry on the center electrode; use a wire gauge and gentle taps."],["What does a fouled plug look like?","Wet, black, or oily deposits shorting the spark — clean or replace it."],["Do hotter plugs add power?","No — heat range must match the engine; wrong range causes damage or fouling."]]},{"title":"Engine Timing and Valve Trains","brief":"The choreography of valves, cams, chains, and belts that breathes the engine in exact sync with the pistons.","points":["The camshaft opens each valve at a precise crank angle, controlling breathing and power character.","Timing belts are quiet and cheap but must be replaced on schedule; chains last longer but cost more.","Overhead cams (OHC) sit atop the head for high-rpm precision; pushrods keep V8s compact and torquey.","If a belt snaps on an interference engine, pistons smash valves — a catastrophic, expensive failure."],"examples":["A timing-belt service at 100,000 miles preventing a ruined engine.","A classic pushrod V8's lumpy idle from a performance camshaft."],"history":["Overhead camshafts appeared on Peugeots in 1912; Fiat's 1966 twin-cam made DOHC mainstream.","Variable valve timing in the 1980s-90s let one camshaft act like many."],"uses":["Every four-stroke engine's reliability hinges on its valve train design.","High-revving sport bikes and supercars use finger-follower DOHC heads for 14,000+ rpm.","Diesel pushrod engines trade rpm for massive low-end torque."],"qa":[["Belt or chain — which is better?","Chains last longer; belts run quieter and cheaper — follow the service schedule either way."],["What is valve float?","At extreme rpm, springs can't close valves fast enough — upgraded springs or desmodromic systems fix it."],["Can timing be adjusted?","Ignition timing yes, via tune; cam timing requires adjustable gears or VVT systems."]]},{"title":"Pistons and Connecting Rods","brief":"The reciprocating heart of the engine — pistons sealing combustion pressure, rods carrying it to the crank.","points":["Pistons seal the chamber with rings: compression rings hold pressure, oil rings scrape the walls.","Forged pistons survive boost and nitrous that would shatter cast ones.","Connecting rods endure tens of tons of cyclic load; H-beam and I-beam forgings handle big power.","Piston slap when cold and rod knock when worn are sounds every mechanic recognizes."],"examples":["A turbo build upgrading to forged pistons and rods before raising boost.","A diesel's massive steel pistons shrugging off 2,500 psi cylinder pressures."],"history":["Aluminum pistons replaced cast iron in the 1920s, cutting reciprocating weight dramatically.","Hypereutectic and forged alloys in the 1980s-2000s let small engines make big power reliably."],"uses":["Every piston engine's power flows through its pistons and rods.","Racing engines use ultra-light pistons and titanium rods to rev past 15,000 rpm.","Rebuilders measure ring gap and rod bearing clearance in thousandths of an inch."],"qa":[["What is piston ring gap?","The end clearance that lets rings expand with heat — too tight seizes, too loose loses compression."],["Do pistons wear out?","Rings and skirts wear over 150k-300k miles; bore wear decides rebuild time."],["Cast vs forged pistons?","Forged for boost, nitrous, or racing; cast/hypereutectic for quiet, efficient street use."]]},{"title":"Crankshafts","brief":"The backbone that turns piston thrust into smooth rotary power, balanced to survive thousands of rpm.","points":["Crank throws offset each piston's stroke; counterweights cancel the reciprocating forces.","Main bearings carry the crank in the block; rod bearings join it to the connecting rods.","Flat-plane cranks rev fast and scream; cross-plane V8 cranks rumble with uneven firing.","Nitride-hardened and billet cranks handle racing loads that would snap a stock casting."],"examples":["A V8's lopey idle — the cross-plane crank's signature uneven exhaust pulse.","A harmonic balancer replacement curing a mysterious high-rpm vibration."],"history":["Early engines used built-up cranks; one-piece forgings became standard by the 1920s.","Torsional dampers in the 1930s solved crank-snapping vibrations in long sixes and eights."],"uses":["Every piston engine centers on its crankshaft design and balance.","Engine builders mic crank journals to ten-thousandths when blueprinting.","Marine and industrial cranks can weigh tons and run decades between overhauls."],"qa":[["What is crankwalk?","Excessive end-play of the crank from worn thrust bearings — rare but serious."],["Can a crankshaft break?","Yes, from fatigue, detonation, or oil starvation — usually destroying the block too."],["Why balance a crank?","Unbalance shakes bearings apart and caps safe rpm; balancing unlocks smooth revs."]]},{"title":"Cylinder Heads and Combustion Chambers","brief":"Where air, fuel, spark, and flame meet — the head's ports, valves, and chamber shape define an engine's character.","points":["Port shape and valve size set airflow; better breathing means more power at high rpm.","Chamber shapes — wedge, hemispherical, pent-roof — control flame travel and knock resistance.","Multi-valve heads (3, 4, 5 valves per cylinder) breathe better than old two-valve designs.","Head gaskets seal combustion pressure, oil, and coolant between head and block — their failure is infamous."],"examples":["A 4-valve pent-roof head letting a small four-cylinder rev to 8,000 rpm.","A blown head gasket diagnosed by milky oil and white exhaust smoke."],"history":["The 1951 Chrysler Hemi proved the hemispherical chamber's power; Ford's 1960s wedge heads won Le Mans.","Four-valve heads went mainstream in the 1980s-90s for efficiency and power."],"uses":["Cylinder-head porting is the classic hot-rod path to more power.","Diesel heads carry injectors and glow plugs in place of spark plugs.","Rebuilders resurface warped heads and replace valve seats to restore sealing."],"qa":[["What does porting do?","Smooths and enlarges intake/exhaust passages for more airflow and power."],["Why do head gaskets fail?","Overheating warps the head, breaking the seal — prevention is cooling maintenance."],["Aluminum vs iron heads?","Aluminum sheds heat and weight; iron tolerates abuse and is cheaper to fix."]]},{"title":"Engine Displacement and Compression Ratio","brief":"The two numbers that most define an engine: how big it breathes and how hard it squeezes.","points":["Displacement is bore area times stroke times cylinder count — the engine's lung capacity.","Compression ratio is the volume ratio from bottom to top of the stroke — 10:1 is typical for gasoline.","Higher compression extracts more energy per fuel drop but demands higher-octane fuel.","Forced induction raises effective compression, which is why turbo engines run lower static ratios."],"examples":["A 5.0-liter V8's effortless torque versus a 2.0-liter turbo's peaky rush.","A high-compression sport bike engine requiring premium fuel to avoid knock."],"history":["Early engines ran 4:1 compression on poor fuel; tetraethyl lead in the 1920s enabled 7:1 and beyond.","Mazda's SkyActiv-X (2019) runs 16:1 compression with spark-controlled compression ignition."],"uses":["Regulations, taxes, and racing classes are all written around displacement limits.","Engine swaps chase the best displacement-to-weight ratio for the chassis.","Efficiency rules push downsized, high-compression turbo engines everywhere."],"qa":[["Bigger engine always better?","Not for efficiency — right-sizing with boost often beats displacement."],["What is dynamic compression?","Effective ratio considering when the intake valve actually closes — what the fuel really feels."],["Can I raise compression?","Thinner gaskets or milled heads do it, but fuel octane and tuning must follow."]]},{"title":"Engine Management and ECUs","brief":"The computers that run modern engines — thousands of decisions per second on fuel, spark, boost, and emissions.","points":["The ECU reads crank position, airflow, temperatures, and oxygen sensors dozens of times per second.","Fuel and spark maps are 3D tables of rpm vs load, interpolated live for every combustion event.","Closed-loop feedback from O2 sensors trims fueling to hold the ideal 14.7:1 air-fuel ratio.","Drive-by-wire throttles, variable valve timing, and boost control all answer to the ECU."],"examples":["A check-engine light leading to a $25 oxygen sensor instead of a $2,000 catalytic converter.","A stage-1 tune unlocking 40 hp by remapping boost and timing on a turbo car."],"history":["Bosch Motronic in 1979 merged fuel and ignition control into one digital ECU.","OBD-II (1996) standardized diagnostics, letting any scanner talk to any car."],"uses":["Every new car, truck, bike, and outboard runs on an ECU.","Standalone ECUs let racers and swappers fully control custom engine builds.","Fleet telematics read ECU data for maintenance and efficiency."],"qa":[["Can I tune my own ECU?","Yes with the right tools — but bad tunes melt pistons; learn on a dyno."],["What is limp mode?","The ECU's self-protection: limited power when a critical sensor fails."],["Do ECUs learn?","They adapt fuel trims and knock correction to fuel quality and wear over time."]]},{"title":"Exhaust Systems and Catalytic Converters","brief":"The breathing-out side of the engine: manifolds, pipes, mufflers, and the catalysts that clean the exhaust.","points":["Headers use equal-length tuned tubes to scavenge exhaust pulses and add power.","Catalytic converters use platinum, palladium, and rhodium to turn CO, HC, and NOx into CO2, water, and nitrogen.","Mufflers cancel sound waves with chambers and perforated tubes; resonators fine-tune the tone.","Backpressure myths aside, engines want velocity and scavenging, not restriction."],"examples":["A cat-back exhaust giving a V8 its deep rumble without hurting power.","A failed converter diagnosed by rotten-egg smell and a glowing red exhaust."],"history":["Eugene Houdry's catalytic converter work in the 1950s-70s; mandated on US cars from 1975.","Stainless mandrel-bent systems in the 1990s-2000s made aftermarket exhausts last."],"uses":["Every road vehicle needs a tuned, legal exhaust system.","Racing series mandate specific exhaust configurations for sound and parity.","Industrial engines use massive silencers and SCR catalysts to meet emissions."],"qa":[["Do I need backpressure?","No — that's a myth; what matters is exhaust velocity and wave scavenging."],["Why do converters fail?","Oil burning, rich misfires, and age melt or poison the catalyst."],["Straight pipes: good idea?","Loud and often illegal; a quality system makes the same power with manners."]]},{"title":"Emissions Control Systems","brief":"The layered technologies that made modern engines 99 percent cleaner than their 1960s ancestors.","points":["EGR recirculates inert exhaust gas to cool combustion and slash NOx formation.","PCV routes crankcase vapors back into the intake instead of venting them to air.","EVAP systems trap fuel vapors in a charcoal canister and burn them in the engine.","Diesels add DPF particulate filters and SCR urea injection to meet strict NOx and soot limits."],"examples":["A stuck EGR valve causing rough idle and a check-engine light.","A diesel truck's DEF (urea) refill at every oil change keeping NOx in check."],"history":["The 1970 US Clean Air Act forced PCV, EGR, and converters onto cars within a decade.","Dieselgate (2015) showed the cost of cheating — billions in fines and the fall of diesel cars."],"uses":["Every new road vehicle carries a full suite of emissions controls.","Inspection programs test OBD readiness and tailpipe emissions.","Retrofit catalysts and filters clean up older industrial and marine engines."],"qa":[["Can I delete emissions equipment?","It's illegal for road use in most places and usually hurts drivability."],["Why does my diesel regen?","The DPF burns off trapped soot periodically — highway driving helps it complete."],["Do emissions controls hurt power?","Modern systems cost almost nothing; 1960s add-ons were the crude ones."]]},{"title":"Engine Dyno Testing","brief":"Measuring real engine output on a dynamometer — the truth serum of horsepower claims.","points":["Engine dynos bolt to the crankshaft and measure torque directly under controlled load.","Chassis dynos measure at the wheels, showing 10-20 percent less than crank figures from drivetrain loss.","Tuners use dynos to map fuel and spark safely, watching air-fuel ratio and knock in real time.","Correction factors (SAE, DIN) normalize results for temperature, pressure, and humidity."],"examples":["A tuner dialing in a turbo build, gaining 30 whp from fuel and timing tweaks.","A manufacturer certifying an engine's rated power for the brochure."],"history":["Early Prony brakes measured steam engines; Clayton chassis dynos brought testing to shops in the 1970s-80s.","Modern eddy-current and AC dynos simulate full road loads with precision."],"uses":["OEMs certify every engine's power and emissions on dynos.","Race teams develop and validate engines on dynos before they ever hit the track.","Enthusiasts settle bench-racing arguments with dyno sheets."],"qa":[["Crank vs wheel horsepower?","Crank is the engine alone; wheel is what reaches the ground — expect 12-18% less."],["Can a dyno hurt my engine?","A proper operator won't — but sustained full-load pulls stress cooling and tires."],["Why do numbers vary between dynos?","Different types, calibrations, and correction factors — compare same-dyno results."]]},{"title":"Engine Tuning and Performance","brief":"The art and science of extracting more power — intakes, exhausts, cams, boost, and calibration.","points":["Stage upgrades stack: intake and exhaust first, then cams or boost, then fuel system and internals.","Forced induction gives the biggest gains per dollar on a strong stock bottom end.","A proper tune is mandatory with hardware changes — parts without calibration can destroy engines.","Data logging (AFR, knock, IAT) separates safe tunes from time bombs."],"examples":["A bolt-on intake and tune waking up a sleepy economy car.","A built 2JZ or LS making quadruple stock power on boost and E85."],"history":["1960s hot-rodders swapped cams and carbs; 1990s import tuners chipped ECUs.","Modern flex-fuel E85 tunes unlock huge gains on turbo cars thanks to ethanol's knock resistance."],"uses":["Motorsport lives on tuning — every race engine is a tuned engine.","Diesel tuners chase torque for towing within transmission limits.","Enthusiast culture spans forums, dyno days, and time-attack events."],"qa":[["How much power is safe on stock internals?","Depends on the engine — research your platform's known limits before adding boost."],["Is E85 worth it?","On turbo cars, yes — big knock resistance and cooling, at the cost of 30% more fuel flow."],["Will tuning void my warranty?","Powertrain warranty claims can be denied if the tune caused the failure."]]},{"title":"Jet Engines (Gas Turbines)","brief":"Continuous-combustion turbines that compress air, burn fuel in it, and extract power — the core of modern aviation.","points":["A compressor squeezes incoming air to 20-40 times atmospheric pressure.","Fuel burns continuously in the combustor, and the hot gas spins the turbine.","The turbine drives the compressor; leftover energy becomes thrust or shaft power.","Turbines thrive on steady high power — they are inefficient at idle and part load."],"examples":["A power-plant gas turbine generating electricity for a city.","A turboshaft in a helicopter converting jet power to rotor lift."],"history":["Frank Whittle patented the turbojet in 1930; Hans von Ohain's HeS 3 flew first in 1939.","The 1950s-60s jet age made global air travel routine."],"uses":["Airliners, fighters, and business jets all fly on gas-turbine power.","Turboshafts drive helicopters, tanks (M1 Abrams), and naval ships.","Industrial gas turbines generate peaking power and drive pipelines."],"qa":[["Why do jets take time to spool?","The massive compressor-turbine spool has huge inertia — seconds from idle to full power."],["How efficient are they?","Large turbofans reach ~40% thermal efficiency; small turbines are far thirstier."],["Can turbines burn anything?","Nearly — kerosene, diesel, natural gas, even peanut oil in a pinch."]]},{"title":"Turboprop Engines","brief":"Gas turbines driving propellers through a reduction gearbox — the efficiency kings of regional aviation.","points":["A gas-turbine core drives a propeller through gears that cut 30,000 rpm to ~1,500.","Propellers are most efficient below 450 mph, where turboprops beat jets on fuel burn.","Reverse thrust comes free — just flatten and reverse propeller pitch on landing.","They are louder in the cabin than jets, the price of propeller efficiency."],"examples":["A regional airliner hopping 300-mile routes cheaper than any jet could.","A C-130 Hercules hauling cargo into short, rough airstrips."],"history":["The 1948 Vickers Viscount was the first turboprop airliner; Rolls-Royce Dart engines made it a hit.","The 1980s-90s regional boom put ATRs and Dash 8s on short routes worldwide."],"uses":["Regional airlines, cargo feeders, and military transports rely on turboprops.","Firefighting air tankers and bush planes need their short-field performance.","Naval patrol and training aircraft favor their economy and loiter time."],"qa":[["Turboprop or jet for short hops?","Turboprop — far less fuel per seat on sub-500-mile sectors."],["Why the gearbox?","Turbines spin far too fast for a propeller; gears match them efficiently."],["Are they safer than pistons?","Turbine reliability is superb — in-flight shutdown rates are minuscule."]]},{"title":"Turbofan Engines","brief":"The big quiet fans under airliner wings — most thrust comes from bypass air, not the jet core.","points":["A huge front fan pushes most air around the core — bypass ratios reach 12:1 on the newest engines.","Only a fraction of air burns fuel; the bypass stream provides the majority of thrust quietly.","High bypass means superb fuel efficiency and low noise — the formula of the jet age.","Geared turbofans let the fan and turbine each spin at ideal speeds, saving more fuel."],"examples":["A GE9X's 134-inch fan — wider than a 737 fuselage — whispering a 777X off the runway.","A business jet's small turbofan balancing speed, range, and quiet cabins."],"history":["The 1960s JT3D and Conway launched the turbofan era on the 707 and DC-8.","The 1990s GE90 and Trent families pushed bypass ratios and reliability to new heights."],"uses":["Every airliner flying today uses high-bypass turbofans.","Fighters use low-bypass afterburning turbofans for supersonic dash.","Military tankers, AWACS, and transports share the same efficient cores."],"qa":[["What is bypass ratio?","Bypass airflow divided by core airflow — higher means quieter and more efficient."],["Why are new engines so big?","Bigger fans move more air slowly — the most efficient way to make thrust."],["How long do they last?","20,000-30,000 hours between overhauls; some run decades."]]},{"title":"Ramjet and Scramjet Engines","brief":"Air-breathing engines with no moving parts that work only at supersonic and hypersonic speeds.","points":["Ramjets use forward speed to ram-compress air — no compressor needed, but they can't start from rest.","Flame holders stabilize combustion in the supersonic-throughflow duct.","Scramjets keep airflow supersonic through the combustor, enabling Mach 5+ flight.","They need a rocket or other booster to reach operating speed — typically Mach 2-3 minimum."],"examples":["A missile like the BrahMos cruising at Mach 3 on ramjet power.","NASA's X-43A scramjet hitting Mach 9.6 in 2004 — the fastest air-breathing flight ever."],"history":["Rene Lorin patented the ramjet concept in 1908; the 1940s-50s built working missiles.","The X-51A Waverider (2010-13) demonstrated sustained scramjet cruise at Mach 5."],"uses":["Supersonic cruise missiles use ramjets for long-range speed.","Hypersonic research vehicles test scramjet propulsion for future strike and space access.","Target drones use simple ramjets for cheap high-speed flight."],"qa":[["Why not on airliners?","They only work at extreme speeds and are inefficient outside a narrow band."],["Ramjet vs scramjet?","Ramjets slow air to subsonic for burning; scramjets burn in supersonic flow for hypersonic flight."],["Any moving parts?","None in the engine itself — elegant, but useless below Mach 2."]]},{"title":"Rocket Engines","brief":"Engines that carry their own oxidizer, making thrust from chemical reactions independent of the atmosphere.","points":["Liquid rockets pump fuel and oxidizer into a chamber, expanding through a nozzle for thrust.","Specific impulse (Isp) measures efficiency — seconds of thrust per unit propellant.","Solid rockets are simple and storable but can't be throttled or shut down once lit.","Regenerative cooling routes cryogenic fuel through chamber walls before burning it."],"examples":["A Falcon 9's nine Merlins throttling and gimbaling to land the booster.","A solid booster lighting with a roar that shakes the ground for miles."],"history":["Robert Goddard launched the first liquid-fuel rocket in 1926; von Braun's V-2 scaled it up in 1944.","The F-1 engines of Saturn V (1967) remain the most powerful single-chamber engines ever flown."],"uses":["Every orbital launch, deep-space probe, and Moon mission rides rocket engines.","Military missiles use solids for instant readiness; space launchers favor throttleable liquids.","RCS thrusters steer spacecraft with tiny precise rocket pulses."],"qa":[["Why multiple engines?","Redundancy, throttling depth, and engine-out capability — SpaceX lands with one of nine."],["What is the most efficient chemical rocket?","Hydrogen-oxygen (RS-25, RL-10) — highest Isp, but bulky cryogenic tanks."],["Can rockets be reused?","Yes — Falcon 9 boosters routinely fly 15+ missions, transforming launch economics."]]},{"title":"Steam Engines","brief":"The engines that launched the industrial revolution — external combustion turning water into work.","points":["Boilers make high-pressure steam; the engine admits it to cylinders or turbines to do work.","Reciprocating steam engines drove factories, ships, and locomotives for over a century.","Steam turbines replaced pistons where smooth high power was needed — power stations and ships.","External combustion burns anything — coal, wood, oil, even waste — a flexibility IC engines lack."],"examples":["A preserved 4-8-4 steam locomotive pulling an excursion train.","A triple-expansion marine engine in a museum, once the heart of an ocean liner."],"history":["James Watt's separate condenser (1769) made steam power efficient enough to industrialize the world.","By 1900 steam powered nearly all rail, sea, and factory machinery."],"uses":["Steam turbines still generate most of the world's electricity — coal, gas, and nuclear plants.","Heritage railways and ships keep reciprocating steam alive for history and tourism.","Solar-thermal and geothermal plants are steam plants with clean heat sources."],"qa":[["Are steam engines efficient?","Old ones ~5-10%; modern steam turbines in combined-cycle plants exceed 60%."],["Why did diesels replace steam on rails?","Diesels needed less labor, water, and maintenance — economics, not romance."],["Could steam come back?","For waste-heat recovery and solar power, steam cycles are already back."]]},{"title":"Stirling Engines","brief":"Silent external-combustion engines running on any heat source, cycling gas between hot and cold ends.","points":["A sealed working gas (helium or hydrogen) shuttles between hot and cold heat exchangers.","Heating expands the gas to drive the piston; cooling contracts it — a closed, clean cycle.","They run on anything hot: sun, biomass, waste heat, even a coffee cup's warmth for toys.","Power density is low and they respond slowly — the historic barriers to wider use."],"examples":["A desktop Stirling fan spinning silently atop a wood stove.","A Dish-Stirling solar concentrator generating power in the desert."],"history":["Robert Stirling patented the engine in 1816 as a safer alternative to steam boilers.","Philips revived Stirling research in the 1930s-50s for quiet generators."],"uses":["Stirling cryocoolers chill infrared sensors and superconducting electronics.","NASA studies Stirling radioisotope generators for decades-long deep-space power.","Combined-heat-and-power home units burn gas for heat and make electricity as a bonus."],"qa":[["Why aren't they in cars?","Slow throttle response and low power density lose to IC engines."],["How efficient can they be?","Well-designed Stirlings approach Carnot limits — 30-40% in practice."],["Do they need fuel?","Only heat — solar, geothermal, or waste heat all work."]]},{"title":"Electric Motors as Engines","brief":"In many catalogs the engine of the electric age: motors converting electricity to motion at 90%+ efficiency.","points":["Electric motors deliver full torque from zero rpm — no clutch, no gears needed for launch.","Regenerative braking recovers energy back into the battery, stretching range.","With one moving part, motors outlast piston engines by multiples with minimal maintenance.","Power electronics (inverters) are the motor's ECU, switching battery DC to precisely timed AC."],"examples":["A Tesla launching silently with instant torque no gearbox could match.","An electric outboard pushing a dinghy with a whisper."],"history":["Anyos Jedlik built an early electric motor in 1828; Tesla's AC induction motor (1888) electrified industry.","The 1990s-2010s lithium-battery revolution made electric cars practical at scale."],"uses":["EVs, e-bikes, scooters, and electric boats all run on motor power.","Industry runs on billions of electric motors — pumps, fans, conveyors, machine tools.","Electric aircraft and drones use motors for quiet, clean propulsion."],"qa":[["Do EVs have transmissions?","Usually a single reduction gear — the motor's wide rpm range needs no shifting."],["How long do EV motors last?","Often the life of the vehicle — bearings are nearly the only wear item."],["AC or DC motors?","Modern EVs use AC induction or permanent-magnet motors driven by inverters."]]},{"title":"Hybrid Powertrains","brief":"Combining combustion engines with electric motors so each covers the other's weaknesses.","points":["Parallel hybrids blend engine and motor torque through one transmission.","Series hybrids use the engine only as a generator; electric motors always drive the wheels.","Power-split systems (Toyota HSD) use a planetary gearset to blend both seamlessly.","Regenerative braking and engine-off coasting deliver the city-mileage magic."],"examples":["A Prius sipping fuel in city traffic on electric assist.","A plug-in hybrid commuting 40 electric miles, then road-tripping on gas."],"history":["Ferdinand Porsche built a series hybrid in 1901; the 1997 Prius made hybrids mainstream.","Formula 1's hybrid era (2014+) proved 50% thermal efficiency is possible."],"uses":["Taxis, delivery fleets, and commuters cut fuel use dramatically with hybrids.","Performance hybrids (McLaren P1, LaFerrari) use electric torque fill for speed.","Locomotives have been diesel-electric series hybrids for nearly a century."],"qa":[["Do hybrids need plugging in?","Regular hybrids self-charge; plug-ins add bigger batteries for electric commuting."],["Is the complexity reliable?","Toyota hybrids are among the most reliable cars made — the system is proven."],["Hybrid vs full EV?","Hybrids need no charging infrastructure; EVs win where charging is easy."]]},{"title":"Hydrogen Combustion Engines","brief":"Burning hydrogen in piston engines — near-zero carbon exhaust using familiar engine technology.","points":["Hydrogen burns with oxygen to make water, so the exhaust is mostly water vapor.","Abnormal combustion (pre-ignition, backfire) is the key challenge — hydrogen ignites easily.","Direct hydrogen injection and careful timing tame combustion for automotive use.","They can leverage existing engine plants and supply chains during the energy transition."],"examples":["A hydrogen-powered Corolla racing in Japan's Super Taikyu series.","A converted truck engine running on hydrogen for carbon-free hauling."],"history":["Hydrogen ICE research ran in the 1970s oil-crisis era; BMW built Hydrogen 7 cars in the 2000s.","Toyota's 2020s hydrogen-engine racing program revived serious development."],"uses":["Motorsport and heavy equipment are the near-term proving grounds.","Backup generators can burn hydrogen where fuel cells are impractical.","Dual-fuel conversions let fleets trial hydrogen on existing engines."],"qa":[["Hydrogen engine or fuel cell?","Engines are cheaper and tougher; fuel cells are more efficient — both are being pursued."],["Where does the hydrogen come from?","Green hydrogen from electrolysis is the clean path; most today is fossil-derived."],["Is it safe?","Hydrogen systems use strict leak detection and venting; it disperses upward fast."]]},{"title":"Engine Materials and Metallurgy","brief":"The alloys and composites that let engines survive fire, pressure, and 200,000-rpm turbos.","points":["Cast iron blocks endure decades of abuse; aluminum blocks save weight and shed heat.","Forged steel cranks and rods handle racing loads; titanium trims reciprocating weight.","Nickel superalloys (Inconel) survive turbine temperatures that melt ordinary steel.","Thermal barrier coatings on pistons and chambers reflect heat into useful work."],"examples":["A compacted-graphite-iron diesel block handling 2,000+ psi cylinder pressure.","Inconel exhaust valves glowing orange in a turbo race engine."],"history":["Aluminum blocks went mainstream in the 1960s-70s (Buick 215, Chevy Vega).","Metal-matrix composites and plasma-transferred cylinder liners cut friction in the 2000s."],"uses":["OEMs pick materials to balance cost, weight, durability, and emissions life.","Aftermarket forgings unlock big power on stock-displacement builds.","Aerospace turbines depend entirely on single-crystal superalloy blades."],"qa":[["Why not all-titanium engines?","Cost — titanium costs 10-50x more than steel to buy and machine."],["Do coatings really help?","Yes — DLC on cams and ceramic on pistons measurably cut friction and heat loss."],["Cast vs forged vs billet?","Cast is cheap, forged is strong, billet is strongest but priciest."]]},{"title":"Engine Bearings","brief":"Tiny precision shells carrying tons of load on films of oil thinner than a hair.","points":["Main bearings support the crankshaft; rod bearings join rods to crank throws.","Tri-metal bearings layer steel, copper-lead or aluminum, and a soft overlay for embedability.","Clearances are measured in thousandths — too tight seizes, too loose hammers.","Oil starvation kills bearings in seconds; the knock of a spun bearing is unmistakable."],"examples":["A rebuild measuring bearing clearance with plastigage before assembly.","A high-mileage engine saved by catching low oil pressure early."],"history":["Babbitt metal bearings carried early engines; precision insert bearings arrived in the 1930s.","Coated race bearings in the 2000s survive marginal lubrication in stop-start engines."],"uses":["Every rotating engine assembly depends on bearing precision.","Engine builders choose bearing clearances for street, race, or boost duty.","Industrial engines use tilting-pad bearings for massive turbine shafts."],"qa":[["What kills bearings?","Dirt, low oil pressure, overheating, and detonation — in that order."],["Can bearings be replaced without a rebuild?","Rod bearings sometimes via the pan; mains usually mean a full teardown."],["Why do race engines use looser clearances?","Thicker oil films at high rpm and heat — matched to racing oil viscosity."]]},{"title":"Gaskets and Seals","brief":"The unsung barriers holding combustion pressure, oil, and coolant in their separate worlds.","points":["Head gaskets seal 2,000+ psi combustion while separating oil and coolant passages.","Multi-layer steel (MLS) gaskets replaced composites for turbo and high-compression duty.","Rear main and front crank seals keep oil inside as the crank spins at thousands of rpm.","Valve stem seals meter a whisper of oil to guides without letting it flood the chambers."],"examples":["A weeping valve cover gasket fixed in an afternoon with basic hand tools.","A rear main seal job — the leak is cheap, the labor to reach it is not."],"history":["Asbestos-composite gaskets ruled until health rules phased them out in the 1980s-90s.","MLS gaskets with their spring-steel layers became standard as specific outputs climbed."],"uses":["Every engine rebuild starts with a full gasket and seal kit.","Boost builders O-ring blocks and use copper gaskets for extreme cylinder pressure.","Restorers hunt NOS gaskets to keep vintage engines original."],"qa":[["Can I reuse a head gasket?","Never — they're crush-to-seal; reuse guarantees a leak."],["What is RTV?","Room-temperature-vulcanizing silicone used in place of or with gaskets on many joints."],["Why do seals leak with age?","Heat hardens rubber; mileage wears the sealing lip — replacement is routine."]]},{"title":"Engine Break-In and Maintenance","brief":"How to run in a new engine and keep any engine healthy for hundreds of thousands of miles.","points":["Break-in seats piston rings to the bore — varied load and rpm for the first 500-1,000 miles.","Early oil changes flush break-in wear metals before they circulate.","Maintenance basics: oil, filters, coolant, plugs, belts — on schedule, without excuses.","Listening for new noises and watching gauges catches most failures before they're fatal."],"examples":["A rebuilt V8's first 500 miles of varied driving, then its first oil change full of glitter.","A 300,000-mile Camry — proof that maintenance beats brand debates."],"history":["1950s manuals demanded 1,000-mile break-ins; modern honing and oils shortened the ritual.","Extended-life coolants and iridium plugs stretched service intervals in the 2000s."],"uses":["Fleet managers live by preventive maintenance schedules and oil analysis.","Aircraft engines follow strict TBO (time between overhaul) rules by law.","DIY owners save thousands with basic maintenance done at home."],"qa":[["Do new cars need break-in?","Gentle varied driving for the first 600-1,000 miles still helps rings seat."],["What maintenance matters most?","Oil changes and cooling system care — they prevent the expensive failures."],["Is premium gas maintenance?","Only if your engine requires it; otherwise it's just expensive regular."]]},{"title":"Engine Overhaul and Rebuilding","brief":"Tearing an engine to its bare block and restoring it to new — or better — condition.","points":["Teardown, cleaning, and measuring decide what can be reused and what must be replaced.","Machine work — boring, honing, decking, crank grinding — restores worn surfaces to spec.","Blueprinting assembles to exact clearances, often better than factory tolerances.","Break-in and tuning validate the rebuild before it returns to service."],"examples":["A 200,000-mile truck engine bored 0.030 over with new pistons, good for another 200k.","A numbers-matching classic V8 rebuilt to stock specs for concours judging."],"history":["Postwar hot-rodders pioneered the home rebuild; 1960s-70s machine shops thrived on V8s.","Crate engines in the 1990s-2000s gave builders factory-fresh performance alternatives."],"uses":["Enthusiasts rebuild classics and performance engines as a rite of passage.","Industrial and marine diesels are routinely overhauled in-frame to extend decades of service.","Remanufactured engines offer warranty-backed replacements for worn motors."],"qa":[["Rebuild or replace?","Rebuild for sentimental/rare engines; crate or reman for common ones — compare costs honestly."],["How long does a rebuild take?","Weeks for a DIY first-timer; days for a pro shop with machine work outsourced."],["What is a stroker?","A longer-throw crank in the same block — more displacement without a bigger engine."]]},{"title":"Small Engines","brief":"The little workhorses of yards and job sites — simple, rugged, and everywhere.","points":["Most are single-cylinder air-cooled four-strokes (or two-strokes) under 25 hp.","Simple carburetors, recoil starters, and splash lubrication keep them cheap and fixable.","Ethanol fuel gums carburetors in storage — stabilizer or ethanol-free fuel prevents it.","Battery-electric tools are rapidly displacing small gas engines for homeowner use."],"examples":["A Honda GX mower engine starting first pull after a decade of service.","A pressure washer's engine roaring to life for spring cleaning."],"history":["Briggs & Stratton's 1908 beginnings grew into the small-engine giant of the 20th century.","Honda's 1960s-70s overhead-valve engines set new standards for quiet reliability."],"uses":["Lawn mowers, trimmers, blowers, tillers, and pressure washers run small engines.","Portable generators and water pumps serve job sites and emergencies.","Go-karts and minibikes introduce generations to engine mechanics."],"qa":[["Why won't my mower start?","Stale fuel gumming the carburetor causes 90% of no-starts — clean or replace the carb."],["Gas or electric tools?","Electric wins for light homeowner use; gas still rules for heavy/professional work."],["How long do they last?","With oil changes and clean air filters, quality small engines run 10-20+ years."]]},{"title":"Marine Engines","brief":"Power for boats — marinized car and truck engines plus purpose-built diesels, all fighting corrosion.","points":["Marinization adds closed cooling (heat exchangers), marine exhausts, and corrosion protection.","Inboards, outboards, sterndrives, and jets each suit different hulls and uses.","Diesels dominate larger boats for torque, economy, and safety (less volatile fuel).","Salt water is the enemy — flushing, anodes, and coatings decide engine life at sea."],"examples":["Twin outboards pushing a center console to the fishing grounds at 50 mph.","A trawler's diesel thumping reliably across an ocean passage."],"history":["Ole Evinrude's 1909 detachable outboard launched recreational boating.","Postwar fiberglass boats and V8 marinization created the modern powerboat era."],"uses":["Fishing, cruising, sailing auxiliaries, and commercial workboats all need marine power.","Ferries and ships scale marine diesels to tens of thousands of horsepower.","Rescue and patrol craft demand instant-start reliability in brutal conditions."],"qa":[["Can I use a car engine in a boat?","Only marinized — marine ignition, fuel, and exhaust rules prevent fires and explosions."],["Gas or diesel boat?","Diesel for big/heavy/long-range; gas outboards for trailerable speed and simplicity."],["How do I winterize?","Fog the cylinders, stabilize fuel, drain/flush cooling, and protect against freezing."]]},{"title":"Aircraft Piston Engines","brief":"Air-cooled flat-fours and sixes that have powered general aviation reliably for nearly a century.","points":["Horizontally opposed cylinders keep the profile low for good pilot visibility and cooling.","Air cooling sheds the weight and failure modes of radiators — critical in the sky.","Dual magnetos and dual spark plugs per cylinder provide ignition redundancy.","They run at 65-75% power for hours — a duty cycle that would destroy a car engine."],"examples":["A Cessna 172's Lycoming humming at 2,400 rpm on a cross-country flight.","A warbird's radial engine coughing to life with smoke and thunder."],"history":["The 1930s-40s perfected the air-cooled flat engine (Lycoming, Continental).","Postwar, thousands of surplus engines seeded the general-aviation boom."],"uses":["Training aircraft, bush planes, and personal aircraft fly behind piston engines.","Agricultural spray planes and gliders' tow planes use their rugged simplicity.","Restorers keep radial-engine warbirds flying as living history."],"qa":[["Why still carburetors and magnetos?","Simplicity and independence from electrical systems — reliability over sophistication."],["What is shock cooling?","Rapid descent cooling that can crack cylinders — pilots descend gently."],["Are they being replaced?","Diesel and electric aircraft engines are emerging, but the fleet turns over slowly."]]},{"title":"Locomotive Diesel Engines","brief":"Thousands of horsepower on rails — almost always diesel-electric, the original hybrid.","points":["A giant diesel (often 16 cylinders, 3,000-6,000 hp) drives a generator, not the wheels.","Electric traction motors on each axle deliver full torque from a standstill.","Dynamic braking turns the motors into generators, dumping energy as heat (or back to wire).","Multiple units (MU) let one crew control several locomotives as one."],"examples":["A freight consist of three 4,400-hp units hauling 100+ cars over a mountain pass.","A switcher idling in the yard, ready for a day of assembling trains."],"history":["EMD's FT demonstrator (1939) proved diesels could replace steam; the 1950s-60s completed the transition.","AC traction motors in the 1990s dramatically improved adhesion and reliability."],"uses":["Freight railroads move a ton of goods 400+ miles per gallon of diesel.","Passenger and commuter rail use diesel-electrics where wires don't reach.","Mining and industrial railways run specialized heavy-haul locomotives."],"qa":[["Why diesel-electric instead of direct drive?","Electric transmission handles the immense torque smoothly with no gearbox."],["How efficient are trains?","The most efficient land transport — steel wheel on steel rail has tiny rolling resistance."],["Will batteries replace them?","Battery and hydrogen locomotives are in trials for yard and short-haul duty."]]},{"title":"Engine Knocking and Detonation","brief":"The destructive abnormal combustion every engine designer and tuner works to prevent.","points":["Knock is the air-fuel mixture auto-igniting from pressure and heat before the flame front arrives.","Detonation hammers pistons with pressure spikes that can shatter ring lands and melt parts.","Higher octane resists auto-ignition, allowing more timing and compression.","Knock sensors hear detonation's signature vibration and pull timing instantly."],"examples":["Pinging under load on cheap gas — cured by a tank of premium.","A turbo engine pulling timing on a hot day, felt as soft power."],"history":["1920s knock research led to tetraethyl lead — effective but toxic; unleaded and sensors replaced it.","Modern ECUs ride the knock threshold constantly for best efficiency."],"uses":["Tuners watch knock religiously — it's the line between power and a windowed block.","Fuel refiners blend octane to meet the needs of the vehicle fleet.","Aircraft pilots manage mixture and manifold pressure to avoid detonation at altitude."],"qa":[["Is light knock harmful?","Occasional trace knock is tolerated; sustained heavy knock destroys engines."],["Does premium add power?","Only in engines designed to advance timing for it — otherwise it's wasted money."],["What is pre-ignition?","Ignition before the spark from a hot spot — even more destructive than knock."]]},{"title":"Engine Efficiency and Thermodynamics","brief":"The physics of turning heat into work — Carnot, Otto, and Diesel cycles set the absolute limits.","points":["No heat engine beats the Carnot limit set by its hot and cold temperatures.","Real engines follow Otto (gasoline) or Diesel cycles, each with its own efficiency math.","Friction, pumping, and heat losses keep real brake efficiency at 20-45%.","Waste-heat recovery (turbocompounding, bottoming cycles) squeezes extra work from exhaust."],"examples":["A Formula 1 hybrid exceeding 50% thermal efficiency — the best piston engine ever.","A combined-cycle gas plant hitting 64% by stacking gas and steam turbines."],"history":["Sadi Carnot's 1824 Reflections founded thermodynamics on steam-engine analysis.","The 1970s oil shocks made efficiency a design priority instead of an afterthought."],"uses":["Every engine program chases efficiency for economy, emissions, and range.","Regulators set fleet efficiency standards that shape the whole industry.","Researchers pursue HCCI, opposed-piston, and waste-heat systems for the next leap."],"qa":[["What is brake specific fuel consumption?","Fuel per unit power — the engineer's mpg; lower is better."],["Why aren't engines 90% efficient?","Thermodynamics forbids it — heat must be rejected; friction and pumping take the rest."],["Most efficient engine ever?","Large marine two-stroke diesels exceed 55%; F1 hybrids top 50%."]]},{"title":"Atkinson and Miller Cycles","brief":"Valve-timing tricks that trade some power density for big efficiency gains — the hybrid engine's secret.","points":["The Atkinson cycle holds the intake valve open into the compression stroke, shortening effective compression.","Expansion exceeds compression, extracting more work from each combustion event.","The Miller cycle adds forced induction to recover the lost power density.","Hybrids love Atkinson engines because the electric motor covers the torque gap."],"examples":["A Prius engine sipping fuel with its late-closing intake valves.","A Mazda Miller-cycle Millenia S supercharged to offset the cycle's power loss."],"history":["James Atkinson's 1882 engine used complex linkages; modern VVT achieves it with valve timing.","Mazda's 1990s Miller-cycle V6 and Toyota's hybrid Atkinsons proved the concept at scale."],"uses":["Nearly all full hybrids run Atkinson-cycle engines for peak efficiency.","Some turbocharged cars use Miller-style late intake closing for economy.","Stationary generators use the cycle where efficiency beats power density."],"qa":[["Does it feel different?","Slightly less low-end punch — invisible in a hybrid with electric assist."],["Can I convert my engine?","No — it needs VVT cam profiles and ECU logic designed for the cycle."],["Why not everywhere?","Where power density matters more than efficiency, conventional cycles win."]]},{"title":"Variable Valve Timing","brief":"Changing when valves open on the fly — one engine that acts like many across the rev range.","points":["VVT advances or retards cam timing with oil-pressure-driven phasers.","Systems like Honda VTEC switch between mild and wild cam profiles entirely.","It broadens the torque curve, cuts emissions, and can enable Atkinson-cycle operation.","Most modern engines vary intake timing; many vary exhaust too."],"examples":["VTEC kicking in with a surge and howl at 6,000 rpm.","A truck's VVT advancing timing for low-end towing torque."],"history":["Alfa Romeo's 1980 Spider had an early production VVT system.","Honda's 1989 VTEC made variable valve timing famous worldwide."],"uses":["VVT is standard on nearly all new gasoline engines.","Diesels use it for emissions control and engine braking.","Performance builds use adjustable cam gears for fine static tuning."],"qa":[["Does VVT fail?","Phasers and solenoids can wear — symptoms are rough idle, codes, and rattles."],["VVT vs VTEC?","VVT continuously varies timing; VTEC switches cam profiles — many engines now do both."],["Can I add VVT?","No — it's designed into the head, cams, oiling, and ECU from the start."]]},{"title":"Engine Starters and Flywheels","brief":"Getting thousands of pounds of machinery spinning — and smoothing the pulses once it runs.","points":["Starters are powerful electric motors that crank the engine via the flywheel ring gear.","The flywheel stores rotational energy, smoothing power pulses between firings.","Dual-mass flywheels add damping springs to absorb diesel and turbo vibration.","Start-stop systems use beefed-up starters and batteries for thousands of extra starts."],"examples":["The whir-click of a starter on a cold morning before the engine catches.","A lightweight flywheel letting a sports car rev and drop rpm in a blink."],"history":["Charles Kettering's 1911 electric starter ended the broken-arm era of hand cranking.","Gear-reduction starters in the 1980s-90s made cranking smaller, lighter, stronger."],"uses":["Every IC engine needs a starting system matched to its compression and size.","Aircraft use powerful starters or air-start carts for big radials and turbines.","Race cars often delete the starter entirely, push-started to save weight."],"qa":[["Why does my starter just click?","Usually a weak battery or corroded cables — not the starter itself."],["Lightweight flywheel: worth it?","Faster revs and response, but easier to stall and more gear noise."],["How long do starters last?","100k-200k miles typically; start-stop cars use heavy-duty units."]]},{"title":"Engine Sensors","brief":"The eyes and ears of the ECU — dozens of sensors reporting every vital sign in real time.","points":["Crank and cam position sensors tell the ECU exactly where each piston is, to the degree.","MAF/MAP sensors measure incoming air so fueling can match it precisely.","Oxygen sensors report exhaust composition for closed-loop mixture control.","Knock, temperature, oil pressure, and throttle sensors complete the picture."],"examples":["A failed crank sensor leaving a car cranking but never starting.","A dirty MAF causing lean codes and hesitation — fixed with a $10 spray cleaner."],"history":["Early EFI used a handful of sensors; OBD-II (1996) standardized dozens of monitored parameters.","Wideband O2 sensors in the 2000s gave tuners laboratory-grade mixture data."],"uses":["Diagnostics and emissions compliance depend entirely on sensor networks.","Fleet telematics stream sensor data for predictive maintenance.","Racing data loggers record hundreds of channels per second."],"qa":[["Which sensor fails most?","O2 sensors and MAF sensors lead the failure charts."],["Can I drive with a sensor unplugged?","The ECU substitutes defaults — poorly; fix it soon."],["Do sensors need calibration?","Most are plug-and-play; some (throttle, steering angle) need relearn procedures."]]},{"title":"Future Engine Concepts","brief":"Opposed pistons, free pistons, rotating detonation — the ideas aiming past today's engines.","points":["Opposed-piston two-strokes (Achates) promise diesel efficiency without a cylinder head.","Free-piston engines drive linear generators directly — no crankshaft at all.","Rotating detonation engines burn fuel in a continuous supersonic wave for huge efficiency gains.","Most target niche roles: range extenders, military power, or efficiency records."],"examples":["An Achates opposed-piston engine demonstrating 50%+ efficiency in testing.","A linear-generator prototype humming as a silent range extender."],"history":["Junkers built opposed-piston aircraft diesels in the 1930s-40s (Jumo 205).","Detonation propulsion research accelerated in the 2010s-20s across the US, China, and Europe."],"uses":["Military labs fund detonation engines for missiles and hypersonic craft.","Automakers prototype free-piston range extenders for future EVs.","Efficiency competitions keep opposed-piston and waste-heat concepts advancing."],"qa":[["Will any replace normal engines?","In niches, yes; the mainstream is electrifying faster than new combustion concepts mature."],["What is HCCI?","Homogeneous charge compression ignition — gasoline that ignites like a diesel for high efficiency."],["Why so slow to market?","Emissions certification and durability testing take a decade; EVs moved the goalposts."]]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief+' This '+angle+' guide provides comprehensive coverage.',genre:angle,type:RECORD_KIND,content:content,demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-engines-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('engines',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();